// Appelle Google Custom Search page par page et renvoie les profils LinkedIn trouvés.
const body = $input.first().json.body || {};
const query = String(body.query || 'ingenieur cloud').slice(0, 120);
const location = String(body.location || '').slice(0, 60);
const maxPages = Math.min(Math.max(parseInt(body.maxPages, 10) || 1, 1), 10);
const q = `${query} ${location} site:linkedin.com/in`.replace(/\s+/g, ' ').trim();

const key = $env.GOOGLE_API_KEY;
const cx = $env.GOOGLE_CX;
if (!key || !cx) throw new Error('GOOGLE_API_KEY ou GOOGLE_CX manquant dans ~/n8n.env');

const out = [];
let start = 1;
for (let page = 0; page < maxPages && start <= 91; page++) {
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://www.googleapis.com/customsearch/v1',
    qs: { key, cx, q, start },
    json: true,
  });
  for (const item of res.items || []) {
    const parts = String(item.title || '').split(' - ');
    out.push({ json: {
      name: parts[0] || null,
      title: parts.slice(1).join(' - ') || null,
      link: item.link || null,
      snippet: item.snippet || null,
      image: item.pagemap?.cse_thumbnail?.[0]?.src || null,
    } });
  }
  const next = res.queries?.nextPage?.[0]?.startIndex;
  if (!next) break;
  start = next;
  await new Promise((r) => setTimeout(r, 400));
}

// Un item au moins, sinon le webhook ne répond jamais.
return out.length ? out : [{ json: { link: null } }];
